import { Fragment } from 'react';

export function TombolBeli() {
  return <button>Beli</button>;
}

function TombolUtama() {
  return <button>Lihat semua produk</button>;
}

export default function App() {
  return (
    <Fragment>
      <h1>Toko Budi</h1>
      <TombolBeli />{' '}
      <TombolUtama />
    </Fragment>
  );
}
